import threading

count = 0

def worker():
    global count
    for _ in range(1_000_000):
        count += 1            # LOAD count; ADD 1; STORE count

ts = [threading.Thread(target=worker) for _ in range(2)]
for t in ts: t.start()
for t in ts: t.join()
print(count)   # always 2_000_000?

